import os
import hashlib
from decimal import Decimal, ROUND_HALF_UP

import stripe
from langchain_core.tools import tool

stripe.api_key = os.environ["STRIPE_SECRET_KEY"]

_ALLOWED_REASONS = {"duplicate", "fraudulent", "requested_by_customer"}


def _to_minor_units(amount):
    return int((Decimal(str(amount)) * 100).quantize(Decimal("1"), rounding=ROUND_HALF_UP))


def _idempotency_key(payment_intent_id, invoice_number, minor_amount):
    raw = f"refund:{payment_intent_id}:{invoice_number}:{minor_amount}"
    return hashlib.sha256(raw.encode()).hexdigest()


@tool
def refund_invoice_payment(
    payment_intent_id: str,
    invoice_number: str,
    amount: float = 0,
    reason: str = "requested_by_customer",
    note: str = "",
) -> dict:
    """Refund an invoice payment via Stripe, fully or partially."""
    normalized_reason = reason if reason in _ALLOWED_REASONS else "requested_by_customer"
    minor_amount = _to_minor_units(amount) if amount else 0

    refund_params = {
        "payment_intent": payment_intent_id,
        "reason": normalized_reason,
        "metadata": {
            "invoice_number": invoice_number,
            "note": note[:500],
            "source": "billing-agent",
        },
    }
    if minor_amount > 0:
        refund_params["amount"] = minor_amount

    key = _idempotency_key(payment_intent_id, invoice_number, minor_amount)

    try:
        refund = stripe.Refund.create(**refund_params, idempotency_key=key)
    except stripe.error.StripeError as exc:
        return {
            "ok": False,
            "invoice_number": invoice_number,
            "error": getattr(exc, "user_message", None) or str(exc),
        }

    refunded_major = Decimal(refund.amount) / 100
    return {
        "ok": True,
        "refund_id": refund.id,
        "invoice_number": invoice_number,
        "status": refund.status,
        "amount": str(refunded_major),
        "currency": refund.currency.upper(),
        "reason": normalized_reason,
    }
